  3	/**
  4	 * @file Change-set vocabulary and persistence contract (ADR-008).
  5	 *
  6	 * Purpose:
  7	 * Defines the durable rows that make every mutation auditable and revertible,
  8	 * for human and AI actors alike.
  9	 *
 10	 * How it relates to the project:
 11	 * - `command.ts` records one change set per executed command.
 12	 * - `revert.ts` walks items in reverse to undo an applied change set.
 13	 * - `repo.memory.ts` provides the in-memory adapter for local dev/tests.
 14	 *
 15	 * Architectural role:
 16	 * This is the storage shape ADR-008 requires to land with the first persistent
 17	 * schema. SQLite/Postgres adapters must satisfy `ChangeSetRepoPort` unchanged.
 18	 */
 19	export type ChangeSetStatus = "proposed" | "applied" | "reverted" | "discarded";
 20	
 21	export type ChangeSetOperation = "create" | "update" | "delete" | "activate";
 22	
 23	/** Durable header row for one reviewable, revertible unit of change. */
 24	export interface ChangeSetRecord {
 25	  id: UUID;
 26	  workspaceId: UUID;
 27	  /** Principal (user or agent) that caused the change. */
 28	  actorId?: UUID;
 29	  status: ChangeSetStatus;
 30	  /** Human-readable description shown in audit/review UIs. */
 31	  summary: string;
 32	  /** Client-supplied key that makes retried commands safe to reject. */
 33	  idempotencyKey?: string;
 34	  /** Link back to the chat message / plan step that motivated the change. */
 35	  intentRef?: string;
 36	  createdAt: ISODateTime;
 37	  appliedAt?: ISODateTime;
 38	  revertedAt?: ISODateTime;
 39	}
 40	
 41	/** One entity mutation inside a change set. */
 42	export interface ChangeSetItemRecord {
 43	  id: UUID;
 44	  changeSetId: UUID;
 45	  /** Entity type key used to resolve an inverse applier, e.g. `post`. */
 46	  entityType: string;
 47	  entityId: UUID;
 48	  operation: ChangeSetOperation;
 49	  /** Revision pointers for revisioned entity types (ADR-008). */
 50	  beforeRevisionId?: UUID;
