134	  for (const subscription of matches) {
135	    const duplicate = await isAlreadyEnqueued({
136	      deliveryRepo: deps.deliveryRepo,
137	      workspaceId: event.workspaceId,
138	      subscriptionId: subscription.id,
139	      eventId: event.id,
140	    });
141	    if (duplicate) continue;
142	
143	    const now = deps.clock.nowIso();
144	    const record: WebhookDeliveryRecord = {
