150	      status: "pending",
151	      attempts: 0,
152	      nextAttemptAt: now,
153	      lastResponseStatus: null,
154	      lastError: null,
155	      signedWithVersion: null,
156	      createdAt: now,
157	      deliveredAt: null,
158	      deadAt: null,
