 97	 */
 98	function topicMatches(subscribedTopics: readonly WebhookTopic[], topic: WebhookTopic): boolean {
 99	  return subscribedTopics.some((pattern) => {
100	    if (pattern === "*") return true;
101	    if (pattern === topic) return true;
102	    if (pattern.endsWith(".*")) {
103	      const entityPrefix = pattern.slice(0, -1);
104	      return topic.startsWith(entityPrefix);
105	    }
106	    return false;
107	  });
108	}
