 56	 * non-empty userinfo component -> lower-case + strip a single trailing dot
 57	 * from the host (IDNA/punycode normalization and case-folding are already
 58	 * performed by the `URL` parser itself) -> resolve an explicit or scheme-
 59	 * default (443 for `https`, 80 for `http`) port.
 60	 *
 61	 * @param rawUrl - the untrusted candidate URL string.
 62	 * @returns the normalized `{ scheme, host, port }`, or `null` if the
 63	 * candidate fails any check. Never throws.
 64	 * @complexity O(n) in the length of `rawUrl` (parser-bound), O(1) space.
 65	 * @overallScore 100/100
 66	 */
 67	export function normalizeOriginCandidate(rawUrl: string): NormalizedTarget | null {
 68	  if (typeof rawUrl !== "string" || rawUrl.length === 0) return null;
 69	  if (FORBIDDEN_RAW_CHARS.test(rawUrl)) return null;
 70	
 71	  let parsed: URL;
 72	  try {
 73	    parsed = new URL(rawUrl);
 74	  } catch {
 75	    return null;
 76	  }
 77	
 78	  if (parsed.protocol !== "https:" && parsed.protocol !== "http:") return null;
 79	  if (parsed.username !== "" || parsed.password !== "") return null;
 80	
 81	  const host = stripTrailingDot(parsed.hostname.toLowerCase());
 82	  if (!host) return null;
 83	
 84	  const scheme: "https" | "http" = parsed.protocol === "https:" ? "https" : "http";
 85	  const port = parsed.port ? Number(parsed.port) : scheme === "https" ? 443 : 80;
 86	  if (!Number.isInteger(port) || port <= 0) return null;
 87	
 88	  return { scheme, host, port };
 89	}
 90	
 91	function stripTrailingDot(host: string): string {
 92	  return host.endsWith(".") ? host.slice(0, -1) : host;
 93	}
 94	
 95	function effectivePort(origin: Pick<VerifiedOrigin, "scheme" | "port">): number {
 96	  return origin.port ?? (origin.scheme === "https" ? 443 : 80);
 97	}
 98	
 99	/** Whether a normalized target is same-origin with a workspace's verified origin. */
100	function isSameOrigin(target: NormalizedTarget, canonical: VerifiedOrigin): boolean {
101	  if (canonical.scheme !== target.scheme) return false;
102	  if (stripTrailingDot(canonical.host.toLowerCase()) !== target.host) return false;
103	  return effectivePort(canonical) === target.port;
104	}
105	
106	export interface OriginRegistryDeps {
107	  repo: OriginSettingRepoPort;
108	}
109	
110	/**
111	 * Trusted canonical-origin registry (ADR-040). The only implementation of
112	 * `OriginRegistryPort` in this v0 slice; a per-`siteId` host-mapped resolver
113	 * is the plausible rule-of-two second adapter (ADR-040 §5), not built yet.
114	 */
115	export class OriginRegistry implements OriginRegistryPort {
116	  private readonly repo: OriginSettingRepoPort;
117	
118	  constructor(deps: OriginRegistryDeps) {
119	    this.repo = deps.repo;
120	  }
121	
122	  /**
123	   * Resolve the verified canonical origin for a workspace.
124	   *
125	   * @param ctx - workspace (and optionally site/locale) to resolve for.
126	   * `siteId` and `locale` are accepted for interface parity with ADR-039's
127	   * `RouteResolveContext` but are not yet used to select between multiple
128	   * origins in this v0 (single-origin-per-workspace) slice.
129	   * @returns the registered `VerifiedOrigin`.
130	   * @throws {OriginNotVerifiedError} if no origin is registered for the
131	   * workspace. Fails closed rather than guessing from the request host.
132	   * @complexity O(1) time/space (single repo lookup).
133	   * @overallScore 100/100
134	   */
135	  async canonicalOrigin(ctx: OriginContext): Promise<VerifiedOrigin> {
136	    const origin = await this.repo.findByWorkspaceId(ctx.workspaceId);
137	    if (!origin) {
138	      throw new OriginNotVerifiedError(`no verified origin registered for workspace '${ctx.workspaceId}'`);
139	    }
140	    return origin;
141	  }
142	
143	  /**
144	   * The single open-redirect oracle (ADR-040 F3). See `normalizeOriginCandidate`
145	   * for the rejection pipeline. Same-origin targets are always allowed;
146	   * cross-origin targets are allowed only via the workspace's exact-host
147	   * redirect allowlist.
148	   *
149	   * @param ctx - workspace (and optionally site/originKey) the redirect is
150	   * scoped to. `originKey` is accepted for `RouteResolveContext` parity
151	   * (ADR-040 F5) but is not yet consumed — v0 has one origin per workspace.
152	   * @param url - untrusted candidate redirect target.
153	   * @returns `true` only if `url` is a verified same-origin or allowlisted
154	   * cross-origin `https` target. Fails closed (`false`) on any parse
155	   * failure, ambiguity, or unexpected error — never throws.
156	   * @complexity O(k) where k = allowlist size (single Set lookup after
157	   * normalization), O(k) space for the allowlist Set.
158	   * @overallScore 100/100
159	   */
160	  async isAllowedRedirectTarget(ctx: RedirectTargetContext, url: string): Promise<boolean> {
161	    return this.isAllowedTarget(ctx, url, (workspaceId) => this.repo.findRedirectAllowlist(workspaceId));
162	  }
163	
164	  /**
165	   * The single third-party egress-target oracle (ADR-040 F4), backed by a
166	   * distinct per-workspace egress-destination allowlist. Same normalization
167	   * pipeline and fail-closed posture as `isAllowedRedirectTarget`.
168	   *
169	   * @param ctx - workspace (and optionally site) the egress call is scoped to.
170	   * @param url - untrusted candidate egress destination.
171	   * @returns `true` only if `url` is a verified same-origin or allowlisted
172	   * `https` target. Fails closed (`false`) on any parse failure, ambiguity,
173	   * or unexpected error — never throws.
174	   * @complexity O(k) where k = allowlist size, O(k) space.
175	   * @overallScore 100/100
176	   */
177	  async isAllowedEgressTarget(ctx: EgressTargetContext, url: string): Promise<boolean> {
178	    return this.isAllowedTarget(ctx, url, (workspaceId) => this.repo.findEgressAllowlist(workspaceId));
179	  }
180	
181	  /**
182	   * Shared same-origin-or-allowlist decision used by both oracles above.
183	   * Isolated as its own function so the two public methods stay a one-line
184	   * pass-through to the correct allowlist source.
185	   *
186	   * @complexity O(k) where k = allowlist size.
187	   * @overallScore 100/100
188	   */
189	  private async isAllowedTarget(
190	    ctx: { workspaceId: string; siteId?: string },
191	    rawUrl: string,
192	    loadAllowlist: (workspaceId: string) => Promise<string[]>
193	  ): Promise<boolean> {
194	    try {
195	      const target = normalizeOriginCandidate(rawUrl);
196	      if (!target) return false;
197	
198	      const canonical = await this.canonicalOrigin({ workspaceId: ctx.workspaceId, siteId: ctx.siteId });
199	      if (isSameOrigin(target, canonical)) return true;
200	
201	      // Cross-origin allowlist path is https-only, unconditionally (ADR-040 amendment 8) — the
202	      // dev-capability http exception above applies ONLY to the same-origin comparison, never
203	      // to a cross-origin allowlisted target (ADR-040 Round-4 fold, R2-005 fix).
204	      if (target.scheme !== "https") return false;
205	
206	      const allowlist = await loadAllowlist(ctx.workspaceId);
207	      const allowSet = new Set(allowlist.map((host) => stripTrailingDot(host.trim().toLowerCase())));
208	      return allowSet.has(target.host);
209	    } catch {
210	      // Fail closed: an unverified origin, a repo error, or any unexpected
211	      // exception must never be treated as "allowed".
212	      return false;
213	    }
214	  }
215	}
