 68	/**
 69	 * Storage seam behind `OriginRegistryPort`: the verified origin plus the two
 70	 * distinct per-workspace allowlists (redirect targets, egress targets).
 71	 */
 72	export interface OriginSettingRepoPort {
 73	  /** The workspace's verified origin, or `null` if none is registered yet. */
 74	  findByWorkspaceId(workspaceId: UUID): Promise<VerifiedOrigin | null>;
 75	  /** Exact-match hosts allowed as cross-origin redirect targets. */
 76	  findRedirectAllowlist(workspaceId: UUID): Promise<string[]>;
