  2	 * @file In-memory `OriginSettingRepoPort` double.
  3	 *
  4	 * Purpose:
  5	 * Test/dev double for the origin-setting store: one `VerifiedOrigin` per
  6	 * workspace plus that workspace's redirect and egress allowlists. No SQLite
  7	 * adapter exists yet (out of scope for this library-layer slice); this is the
  8	 * only implementation of `OriginSettingRepoPort` for now.
  9	 */
 10	import type { UUID } from "../core/ports";
 11	import type { OriginSettingRepoPort } from "./ports";
 12	import { createVerifiedOrigin, type VerifiedOrigin } from "./types";
 13	
 14	/** One workspace's seed data for `InMemoryOriginSettingRepo`. */
 15	export interface OriginSettingSeed {
 16	  workspaceId: UUID;
 17	  origin: VerifiedOrigin;
 18	  /** Exact-match hosts allowed as cross-origin redirect targets. */
 19	  redirectAllowlist?: string[];
 20	  /** Exact-match hosts allowed as third-party egress destinations. */
 21	  egressAllowlist?: string[];
 22	}
 23	
 24	/**
 25	 * In-memory `OriginSettingRepoPort`. Seed it with one entry per workspace;
 26	 * e.g. for local dev/tests, seed `{ scheme: "https", host: "localhost",
 27	 * port: 3000, source: "dev-capability", verifiedAt: <now> }` as the
 28	 * workspace's dev-capability origin.
 29	 */
 30	export class InMemoryOriginSettingRepo implements OriginSettingRepoPort {
 31	  private readonly origins: Map<UUID, VerifiedOrigin>;
 32	  private readonly redirectAllowlists: Map<UUID, string[]>;
 33	  private readonly egressAllowlists: Map<UUID, string[]>;
 34	
 35	  constructor(seeds: OriginSettingSeed[] = []) {
 36	    this.origins = new Map();
 37	    this.redirectAllowlists = new Map();
 38	    this.egressAllowlists = new Map();
 39	
 40	    for (const seed of seeds) {
 41	      this.origins.set(seed.workspaceId, createVerifiedOrigin(seed.origin));
 42	      this.redirectAllowlists.set(seed.workspaceId, normalizeHostList(seed.redirectAllowlist));
 43	      this.egressAllowlists.set(seed.workspaceId, normalizeHostList(seed.egressAllowlist));
 44	    }
 45	  }
 46	
 47	  async findByWorkspaceId(workspaceId: UUID): Promise<VerifiedOrigin | null> {
 48	    return this.origins.get(workspaceId) ?? null;
 49	  }
 50	
 51	  async findRedirectAllowlist(workspaceId: UUID): Promise<string[]> {
 52	    return this.redirectAllowlists.get(workspaceId) ?? [];
 53	  }
 54	
 55	  async findEgressAllowlist(workspaceId: UUID): Promise<string[]> {
 56	    return this.egressAllowlists.get(workspaceId) ?? [];
 57	  }
 58	}
