 97	 * `__tests__/media-service.test.ts`) rather than an implicit one enforced only
 98	 * by "the type doesn't have the field" — and it's the seam any future
 99	 * "replace source" operation would have to go through.
100	 *
101	 * @complexity O(1).
102	 * @overallScore 100
103	 */
104	export function resolveWriteOnceSource(
105	  existing: MediaSource | undefined,
106	  requestedSha256: string
107	): MediaSource {
108	  if (existing && existing.sha256 !== requestedSha256) {
109	    throw new MediaSourceImmutableError(
110	      `source.sha256 is write-once: cannot change '${existing.sha256}' to '${requestedSha256}'`
111	    );
112	  }
113	  return { sha256: requestedSha256 };
114	}
