124	
125	export interface UploadMediaInput {
126	  workspaceId: UUID;
127	  bytes: Uint8Array;
128	  filename: string;
129	  contentType: string;
130	  alt?: string;
131	  caption?: string;
132	  credit?: string;
133	  /** Attributed on the `asset_blobs` row (ADR-027 §2 required attribution). */
134	  createdByPrincipal: string;
135	}
136	
137	export interface UploadMediaDeps {
138	  clock: ClockPort;
139	  idGen: IdGeneratorPort;
140	  mediaRepo: MediaRepoPort;
141	  blobRepo: AssetBlobRepoPort;
142	  renditionRepo: AssetRenditionRepoPort;
143	  blobStore: BlobStorePort;
144	}
145	
146	export interface UploadMediaRequired {
147	  deps: UploadMediaDeps;
148	  input: UploadMediaInput;
149	}
150	
151	export interface UploadMediaOptional {
152	  maxUploadBytes?: number;
153	  allowedMimeTypes?: ReadonlySet<string>;
154	}
155	
156	/**
157	 * Validates, hashes, dedups by `(workspaceId, sha256)`, and writes a new media
158	 * asset. Ordering (ADR-027 §5 INV-1a): bytes are written (or found already
159	 * present via dedup) BEFORE the media row is saved — a media row never exists
160	 * without corresponding bytes.
161	 *
162	 * Blob dedup is per-hash, not per-upload: uploading the same bytes twice
163	 * always creates two `MediaRecord`s (two distinct library entries, matching
164	 * common CMS behavior) but writes the blob bytes only once. The dedup
165	 * check-then-act sequence runs inside {@link withSha256Lock} (`blob-gc-lock.ts`)
166	 * so it can't interleave with a concurrent `blob-gc.ts` delete-pass on the
167	 * same sha256 (ADR-027 §5's "Serialization" clause). If the existing blob row
168	 * is `tombstoned` (a pending GC candidate), this resurrects it back to
169	 * `active` in the same locked section instead of writing a duplicate blob —
170	 * the dedup rule's explicit resurrect case.
171	 *
172	 * @complexity O(1) — one hash, one blob lookup, at most one blob write, one
173	 * media write, one rendition write (the lock itself adds O(1) scheduling
174	 * overhead, not a scan).
175	 * @overallScore 100
176	 */
177	export async function uploadMedia(
178	  required: UploadMediaRequired,
179	  optional: UploadMediaOptional = {}
180	): Promise<{ media: MediaRecord }> {
181	  const { deps, input } = required;
182	  const maxUploadBytes = optional.maxUploadBytes ?? DEFAULT_MAX_UPLOAD_BYTES;
183	  const allowedMimeTypes = optional.allowedMimeTypes ?? DEFAULT_ALLOWED_MIME_TYPES;
184	
185	  if (!allowedMimeTypes.has(input.contentType)) {
186	    throw new MediaValidationError(
187	      `content type '${input.contentType}' is not allowed for upload`
188	    );
189	  }
190	  if (input.bytes.byteLength === 0) {
191	    throw new MediaValidationError("uploaded file is empty");
192	  }
193	  if (input.bytes.byteLength > maxUploadBytes) {
194	    throw new MediaValidationError(
195	      `uploaded file exceeds the ${maxUploadBytes}-byte size cap`
196	    );
197	  }
198	
199	  const sha256 = createHash("sha256").update(input.bytes).digest("hex");
200	  const nowIso = deps.clock.nowIso();
201	
202	  const storageKey = await withSha256Lock(sha256, async () => {
203	    const existingBlob = await deps.blobRepo.findByHash({ workspaceId: input.workspaceId, sha256 });
204	    if (existingBlob) {
205	      if (existingBlob.status === "tombstoned") {
206	        // Resurrect: cancel the pending GC in the same locked section rather
207	        // than writing a duplicate blob (ADR-027 §5 INV-1 dedup rule).
208	        await deps.blobRepo.save({ ...existingBlob, status: "active", tombstonedAt: undefined });
209	      }
210	      return existingBlob.storageKey;
211	    }
212	
213	    const written = await deps.blobStore.put({
214	      workspaceId: input.workspaceId,
215	      sha256,
216	      bytes: input.bytes,
217	    });
218	    await deps.blobRepo.save({
219	      id: deps.idGen.newId(),
220	      workspaceId: input.workspaceId,
221	      sha256,
222	      storageKey: written.storageKey,
223	      status: "active",
224	      createdByPrincipal: input.createdByPrincipal,
225	      createdAt: nowIso,
226	    });
227	    return written.storageKey;
228	  });
229	
230	  const media: MediaRecord = {
231	    id: deps.idGen.newId(),
232	    workspaceId: input.workspaceId,
233	    title: deriveTitleFromFilename(input.filename),
234	    alt: input.alt?.trim() ?? "",
235	    caption: input.caption?.trim() ?? "",
236	    credit: input.credit?.trim() ?? "",
237	    source: resolveWriteOnceSource(undefined, sha256),
238	    status: "active",
239	    createdAt: nowIso,
240	    updatedAt: nowIso,
241	    version: 1,
242	  };
243	  await deps.mediaRepo.save(media);
244	
245	  await deps.renditionRepo.save({
246	    id: deps.idGen.newId(),
247	    workspaceId: input.workspaceId,
248	    assetId: media.id,
249	    transformName: "original",
250	    version: 1,
251	    storageKey,
252	    createdAt: nowIso,
253	  });
254	
255	  return { media };
256	}
