 39	/**
 40	 * Registers a named transform definition. Append-only (ADR-027 §4):
 41	 * redefining an already-used `name` never mutates the prior version's row —
 42	 * it inserts a new row at `version = (current max version for name) + 1`
 43	 * (or `1` if `name` has never been registered). The read-max-then-insert
 44	 * sequence runs inside {@link withTransformRegistryLock} keyed on
 45	 * `(workspaceId, name)` so two concurrent `registerTransform` calls for the
 46	 * same name can't both observe the same "current max" and mint colliding
 47	 * versions (the version-numbering equivalent of the race
 48	 * `withSha256Lock`/`blob-gc-lock.ts` closes for blob dedup-vs-GC).
 49	 *
 50	 * @complexity O(v) in the number of existing versions of `name`, from the
 51	 * max-version scan (`listByName` + reduce) — acceptable at walking-skeleton
 52	 * scale, same tradeoff class as `isBlobUnreferenced`'s O(n) scan.
 53	 * @overallScore 100
 54	 */
 55	export async function registerTransform(
 56	  required: RegisterTransformRequired,
 57	  _optional: Record<string, never> = {}
 58	): Promise<{ definition: TransformDefinitionRecord }> {
 59	  const { deps, input } = required;
 60	
 61	  const name = input.name.trim();
 62	  if (!name) throw new TransformValidationError("transform name is required");
 63	  const owner = input.owner.trim();
 64	  if (!owner) throw new TransformValidationError("owner is required");
 65	  assertValidTransformParams(input.params);
 66	
 67	  return withTransformRegistryLock(`${input.workspaceId}:${name}`, async () => {
 68	    const existingVersions = await deps.transformRepo.listByName({ workspaceId: input.workspaceId, name });
 69	    const currentMaxVersion = existingVersions.reduce((max, row) => Math.max(max, row.version), 0);
 70	
 71	    const definition: TransformDefinitionRecord = {
 72	      id: deps.idGen.newId(),
 73	      workspaceId: input.workspaceId,
 74	      name,
 75	      version: currentMaxVersion + 1,
 76	      params: input.params,
 77	      owner,
 78	      createdAt: deps.clock.nowIso(),
 79	    };
 80	    await deps.transformRepo.insert(definition);
 81	    return { definition };
 82	  });
 83	}
