420	/**
421	 * Hard delete. Deletion ladder (ADR-027 §5, mirrors `deleteMenu`): purge is
422	 * rejected with `MediaStillReferencedError` (409-style) unless the asset has
423	 * already been trashed first.
424	 *
425	 * SIMPLIFICATION (disclosed): the real ADR-027 §5 guard checks the derived
426	 * `entry_refs` where-used index (any live reference from published content).
427	 * That index doesn't exist — posts don't reference media by id in `bodyJson`
428	 * yet — so this build uses "not yet trashed" as the stand-in referenced-check.
429	 * This is strictly weaker than the real invariant: a media asset that IS
430	 * trashed but still referenced by a post would purge here without complaint,
431	 * whereas the real system would keep blocking it. Do not read this function's
432	 * 409 as evidence the where-used index exists.
433	 *
434	 * Once past the guard: rendition rows are removed, then the media row is
435	 * removed. After that removal commits, the blob-GC tombstone-pass
436	 * (`tombstoneBlobIfUnreferenced`, `blob-gc.ts`) runs for the asset's sha256 —
437	 * it marks the blob `tombstoned` if-and-only-if the real "unreferenced"
438	 * predicate holds (no other non-purged media row shares the hash, plus the
439	 * disclosed `entry_refs`/retained-snapshot stubs). This function does **not**
440	 * delete blob bytes itself anymore: the delete-pass (`runBlobGcDeletePass`)
441	 * is grace-period-gated (`gc_grace`, default 30 days) and the unlink-pass
442	 * (`runBlobGcUnlinkPass`) that actually removes bytes runs as a separate,
443	 * explicit step — nothing in this repo schedules either automatically yet
444	 * (see `blob-gc.ts`'s file header). This is a real behavior change from this
445	 * function's prior "delete row, best-effort unlink immediately" shortcut,
446	 * which is exactly the ADR-027 §5 gap this task closes.
447	 *
448	 * @complexity O(n) in the workspace's media row count, inherited from the
449	 * tombstone-pass's `isBlobUnreferenced` scan (see `blob-gc.ts`).
450	 * @overallScore 100
451	 */
452	export async function purgeMedia(
453	  required: PurgeMediaRequired,
454	  _optional: Record<string, never> = {}
455	): Promise<{ purged: true }> {
456	  const { deps, input } = required;
457	  const existing = await deps.mediaRepo.findById(input);
458	  if (!existing) throw new MediaNotFoundError(`media '${input.id}' was not found`);
459	
460	  if (existing.status !== "trashed") {
461	    throw new MediaStillReferencedError(
462	      `media '${input.id}' must be trashed before it can be purged`,
463	      [
464	        `media '${input.id}' is still active (stand-in for the real ADR-027 §5 entry_refs ` +
465	          `where-used index, which is not implemented — see purgeMedia's doc comment)`,
466	      ]
467	    );
468	  }
469	
470	  await deps.renditionRepo.removeByAsset({ workspaceId: input.workspaceId, assetId: input.id });
471	  await deps.mediaRepo.remove({ workspaceId: input.workspaceId, id: input.id });
472	
473	  const clock = deps.clock ?? { nowIso: () => new Date().toISOString() };
474	  await tombstoneBlobIfUnreferenced({
475	    deps: { mediaRepo: deps.mediaRepo, blobRepo: deps.blobRepo, clock },
476	    input: { workspaceId: input.workspaceId, sha256: existing.source.sha256 },
477	  });
478	
479	  return { purged: true };
480	}
