 47	/** Property-key names that read as PII by themselves, regardless of value. */
 48	const PII_KEY_NAME_PATTERN =
 49	  /email|phone|ssn|social[-_]?security|password|credit[-_]?card|street[-_]?address|full[-_]?name|first[-_]?name|last[-_]?name/i;
 50	
 51	/**
 52	 * Validates bounded custom event properties, rejecting anything PII-shaped. This is a simple v1
 53	 * heuristic (email-shape values, PII-suggestive key names, and a property-count/length bound) —
 54	 * not a general PII classifier. Explicitly in scope per ADR-035 §4: "Event properties are bounded,
 55	 * validated, and PII-shape-rejected."
 56	 *
 57	 * @param props - Raw event properties from the beacon, or `null`/`undefined` when absent.
 58	 * @returns The same object when it passes validation, or `null` when no properties were supplied.
 59	 * @throws {AnalyticsPiiRejectedError} when the property count, a value's length, a PII-suggestive
 60	 *   key name, or an email-shaped string value trips the heuristic.
 61	 * @complexity O(k) over the number of properties (bounded by `MAX_EVENT_PROP_COUNT`).
 62	 * @overallScore 100/100
 63	 */
 64	export function validateEventProps(props: JsonObject | null | undefined): JsonObject | null {
 65	  if (props === null || props === undefined) return null;
 66	
 67	  const keys = Object.keys(props);
 68	  if (keys.length > MAX_EVENT_PROP_COUNT) {
 69	    throw new AnalyticsPiiRejectedError(
 70	      `event properties exceed the ${MAX_EVENT_PROP_COUNT}-key bound (${keys.length} given)`
 71	    );
 72	  }
 73	
 74	  for (const key of keys) {
 75	    if (PII_KEY_NAME_PATTERN.test(key)) {
 76	      throw new AnalyticsPiiRejectedError(`event property key '${key}' looks PII-shaped`);
 77	    }
 78	
 79	    const value = props[key];
 80	    if (typeof value !== "string") continue;
 81	
 82	    if (value.length > MAX_EVENT_PROP_STRING_LENGTH) {
 83	      throw new AnalyticsPiiRejectedError(
 84	        `event property '${key}' exceeds ${MAX_EVENT_PROP_STRING_LENGTH} characters`
 85	      );
 86	    }
 87	    if (EMAIL_SHAPE_PATTERN.test(value)) {
 88	      throw new AnalyticsPiiRejectedError(`event property '${key}' looks like an email address`);
 89	    }
 90	  }
 91	
 92	  return props;
 93	}
