 96	/* Coarse-signal normalization (the PII-death boundary)                       */
 97	/* -------------------------------------------------------------------------- */
 98	
 99	/** Raw per-request signals consumed transiently by `normalizeIngestContext`. */
100	export interface CoarseIngestInput {
101	  ip: string;
102	  userAgent: string;
103	  siteHost: string;
104	}
105	
106	/** The only output of coarse-signal normalization — no `ip`/`userAgent` field exists on this type. */
107	export interface NormalizedIngestContext {
108	  visitorHash: string;
109	  deviceClass: DeviceClass;
110	  browserFamily: string | null;
111	  osFamily: string | null;
112	}
113	
114	const BOT_UA_PATTERN = /bot|crawler|spider|slurp|bingpreview|facebookexternalhit/i;
115	const TABLET_UA_PATTERN = /ipad|tablet|kindle|playbook/i;
116	const MOBILE_UA_PATTERN = /mobi|iphone|android/i;
117	
118	/**
119	 * Classifies a User-Agent string into a coarse device class + browser/OS family. Intentionally
120	 * coarse (family only, never the raw string) — this is the "UA → device class" transient use the
121	 * ADR describes, not a fingerprinting-grade parser.
122	 *
123	 * @complexity O(1) — a fixed, small sequence of regex tests.
124	 * @overallScore 100/100
125	 */
126	function classifyUserAgent(userAgent: string): {
127	  deviceClass: DeviceClass;
128	  browserFamily: string | null;
129	  osFamily: string | null;
130	} {
131	  const ua = userAgent ?? "";
132	
133	  let deviceClass: DeviceClass = "unknown";
134	  if (!ua) deviceClass = "unknown";
135	  else if (BOT_UA_PATTERN.test(ua)) deviceClass = "bot";
136	  else if (TABLET_UA_PATTERN.test(ua)) deviceClass = "tablet";
137	  else if (MOBILE_UA_PATTERN.test(ua)) deviceClass = "mobile";
138	  else deviceClass = "desktop";
139	
140	  let browserFamily: string | null = null;
141	  if (/edg\//i.test(ua)) browserFamily = "edge";
142	  else if (/chrome\//i.test(ua)) browserFamily = "chrome";
143	  else if (/firefox\//i.test(ua)) browserFamily = "firefox";
144	  else if (/safari\//i.test(ua) && !/chrome/i.test(ua)) browserFamily = "safari";
145	  else if (ua) browserFamily = "other";
146	
147	  let osFamily: string | null = null;
148	  if (/windows/i.test(ua)) osFamily = "windows";
149	  else if (/mac os|macintosh/i.test(ua)) osFamily = "macos";
150	  else if (/android/i.test(ua)) osFamily = "android";
151	  else if (/iphone|ipad|ios/i.test(ua)) osFamily = "ios";
152	  else if (/linux/i.test(ua)) osFamily = "linux";
153	  else if (ua) osFamily = "other";
154	
155	  return { deviceClass, browserFamily, osFamily };
156	}
157	
158	/**
159	 * Truncates/buckets an IP address to a coarse prefix (IPv4 /24, IPv6 /48) so the request signal
160	 * folded into `visitorHash` never encodes a full, individually-identifying address.
161	 *
162	 * @complexity O(1).
163	 * @overallScore 100/100
164	 */
165	function truncateIp(ip: string): string {
166	  if (ip.includes(":")) {
167	    const groups = ip.split(":").filter((group) => group.length > 0);
168	    return `${groups.slice(0, 3).join(":")}::`;
169	  }
170	
171	  const octets = ip.split(".");
172	  if (octets.length === 4) {
173	    return `${octets[0]}.${octets[1]}.${octets[2]}.0`;
174	  }
175	
176	  return "unknown";
177	}
178	
179	/**
180	 * The PII-death boundary. Accepts the raw per-request IP/User-Agent as plain function parameters
181	 * (never stored, never attached to any object) and returns only a salted, non-reversible
182	 * `visitorHash` plus coarse device/browser/os classes. `dailySalt` must come from
183	 * {@link deriveDailySalt}; the caller is responsible for its 24h rotation.
184	 *
185	 * `visitorHash = sha256(dailySalt ‖ siteHost ‖ coarseRequestSignal)`, where `coarseRequestSignal`
186	 * is the bucketed IP prefix plus the coarse browser-family/device-class pair (never the raw
187	 * IP/UA string) — see ADR-035 §4 / OQ-2.
188	 *
189	 * @param input - `{ ip, userAgent, siteHost }`, consumed transiently only within this call.
190	 * @param dailySalt - The current day's derived salt (never persisted; see `salt.ts`).
191	 * @returns `{ visitorHash, deviceClass, browserFamily, osFamily }` — deliberately has no `ip` or
192	 *   `userAgent` field, by type, so raw request identifiers cannot leak downstream by accident.
193	 * @complexity O(1).
194	 * @overallScore 100/100
195	 */
196	export function normalizeIngestContext(
197	  input: CoarseIngestInput,
198	  dailySalt: Buffer
199	): NormalizedIngestContext {
200	  const { ip, userAgent, siteHost } = input;
201	
202	  const truncatedIp = truncateIp(ip);
203	  const uaClass = classifyUserAgent(userAgent);
204	  const coarseRequestSignal = `${truncatedIp}|${uaClass.deviceClass}|${uaClass.browserFamily ?? "none"}`;
205	
206	  const visitorHash = createHash("sha256")
207	    .update(dailySalt)
208	    .update(siteHost)
209	    .update(coarseRequestSignal)
210	    .digest("hex");
211	
212	  return {
213	    visitorHash,
214	    deviceClass: uaClass.deviceClass,
215	    browserFamily: uaClass.browserFamily,
216	    osFamily: uaClass.osFamily,
217	  };
218	}
