266	/**
267	 * Finds the first policy reason a hit should be dropped for (DNT/GPC/path/IP exclusion), or
268	 * `null` when none apply. Kept as a pure decision function (no I/O, no side effects) separate
269	 * from `ingestHit`'s effects, per the coding-foundations decision/effect-separation rule.
270	 *
271	 * @complexity O(p + r) over the excluded-paths and excluded-IP-ranges config lists (both small,
272	 *   operator-configured lists — not user-variable-sized collections).
273	 * @overallScore 100/100
274	 */
275	function findExclusionReason(input: {
276	  beacon: IngestBeacon;
277	  ip: string;
278	  config: AnalyticsSiteConfig;
279	}): IngestDropReason | null {
280	  const { beacon, ip, config } = input;
281	
282	  if (config.honorDoNotTrack && beacon.dnt) return "dnt";
283	  if (config.honorGlobalPrivacyControl && beacon.gpc) return "gpc";
284	  if (isPathExcluded(beacon.path, config.excludedPaths)) return "excluded_path";
285	  if (isIpExcluded(ip, config.excludedIpRanges)) return "excluded_ip";
286	  return null;
287	}
288	
289	/** Matches a path against a small set of glob patterns (`*` wildcard only — v1 simplicity). */
290	function isPathExcluded(path: string, excludedPaths: readonly string[]): boolean {
291	  return excludedPaths.some((pattern) => pathMatchesGlob(path, pattern));
292	}
293	
294	function pathMatchesGlob(path: string, pattern: string): boolean {
295	  if (!pattern.includes("*")) return path === pattern;
296	  const regexBody = pattern
297	    .split("*")
298	    .map((segment) => segment.replace(/[.+^${}()|[\]\\]/g, "\\$&"))
299	    .join(".*");
300	  return new RegExp(`^${regexBody}$`).test(path);
301	}
302	
303	/** Matches an IP against a small set of exact addresses or IPv4 CIDR ranges (v1: IPv4 CIDR only). */
304	function isIpExcluded(ip: string, excludedRanges: readonly string[]): boolean {
305	  return excludedRanges.some((range) => ipMatchesRange(ip, range));
306	}
307	
308	function ipMatchesRange(ip: string, range: string): boolean {
309	  if (!range.includes("/")) return ip === range;
310	
311	  const [rangeIp, prefixRaw] = range.split("/");
312	  const prefix = Number(prefixRaw);
313	  if (ip.includes(":") || rangeIp.includes(":") || Number.isNaN(prefix)) return false;
314	
315	  const ipInt = ipv4ToInt(ip);
316	  const rangeInt = ipv4ToInt(rangeIp);
317	  if (ipInt === null || rangeInt === null) return false;
318	
319	  const mask = prefix <= 0 ? 0 : (0xffffffff << (32 - prefix)) >>> 0;
320	  return (ipInt & mask) === (rangeInt & mask);
321	}
322	
323	function ipv4ToInt(ip: string): number | null {
324	  const parts = ip.split(".").map(Number);
325	  if (parts.length !== 4 || parts.some((part) => Number.isNaN(part) || part < 0 || part > 255)) {
326	    return null;
327	  }
328	  return ((parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3]) >>> 0;
329	}
330	
331	/** `YYYY-MM-DD` slice of an ISO timestamp — the salt-rotation boundary (ADR-035 §4, 24h). */
332	function toUtcDate(iso: ISODateTime): string {
333	  return iso.slice(0, 10);
334	}
335	
336	/** Bucket width for the deliberately-simple v1 session id (see `deriveSessionId`). */
337	const SESSION_WINDOW_MINUTES = 30;
338	
339	/**
340	 * Derives a session id from the visitor hash plus a bounded, same-day time window, so it is never
341	 * cross-day linkable (types.ts: "Not cross-day linkable"). This is a v1 simplification of session
342	 * boundary logic (true session stitching — extending a session across window edges — is a
343	 * rollup/session-table concern, out of scope for the ingest-only slice); it is deterministic and
344	 * good enough to satisfy `NormalizedHit.sessionId` at ingest time.
345	 *
346	 * @complexity O(1).
347	 * @overallScore 90/100 — Medium: session-window edges (e.g. a real visit spanning a 30-minute
348	 *   boundary) will get two different session ids at ingest time; true stitching belongs to the
349	 *   later rollup/session-table logic (out of this slice's scope), not fixed here.
350	 */
351	function deriveSessionId(visitorHash: string, occurredAt: ISODateTime): string {
352	  const utcDate = toUtcDate(occurredAt);
353	  const occurredDate = new Date(occurredAt);
354	  const minutesSinceMidnight = occurredDate.getUTCHours() * 60 + occurredDate.getUTCMinutes();
355	  const windowIndex = Math.floor(minutesSinceMidnight / SESSION_WINDOW_MINUTES);
356	
357	  return createHash("sha256").update(`${visitorHash}:${utcDate}:${windowIndex}`).digest("hex");
358	}
