 29	/**
 30	 * Clamps a caller-requested `list()` size into `[1, MAX_LIST_LIMIT]`, substituting
 31	 * {@link DEFAULT_LIST_LIMIT} for `undefined`/non-finite input (e.g. `NaN` from an unparsed query
 32	 * string) rather than propagating it into `Array.prototype.slice`, where a `NaN` argument silently
 33	 * degrades to unrelated (and confusing) slice behavior.
 34	 *
 35	 * @complexity O(1).
 36	 * @overallScore 100/100
 37	 */
 38	function clampListLimit(requested: number | undefined): number {
 39	  if (requested === undefined || !Number.isFinite(requested)) return DEFAULT_LIST_LIMIT;
 40	  return Math.min(Math.max(Math.trunc(requested), 1), MAX_LIST_LIMIT);
 41	}
