 43	/**
 44	 * Minimal in-memory `AnalyticsSinkPort`. Durable within the process only (`capabilities().durable`
 45	 * describes what the sink promises to its callers, not disk persistence — no rollup/storage table
 46	 * backs this adapter; see file header).
 47	 *
 48	 * @complexity O(1) amortized per `accept`/`acceptBatch` call (array append).
 49	 * @overallScore 100/100
 50	 */
 51	export class LocalBufferSink implements AnalyticsSinkPort {
 52	  private hits: NormalizedHit[];
 53	
 54	  constructor(initialHits: NormalizedHit[] = []) {
 55	    this.hits = [...initialHits];
 56	  }
 57	
 58	  capabilities(): AnalyticsSinkCapabilities {
 59	    return { durable: true, batch: true };
 60	  }
 61	
 62	  async accept(hit: NormalizedHit): Promise<void> {
 63	    this.hits.push(hit);
 64	  }
 65	
 66	  async acceptBatch(hits: readonly NormalizedHit[]): Promise<void> {
 67	    this.hits.push(...hits);
 68	  }
 69	
 70	  /** Test/inspection accessor. Returns a defensive copy so callers cannot mutate internal state. */
 71	  all(): NormalizedHit[] {
 72	    return [...this.hits];
 73	  }
 74	
 75	  /**
 76	   * Returns the most recently accepted hits, newest first — the read side behind the admin
 77	   * "recent hits" screen. This is a raw read over the in-memory buffer, NOT an aggregate/rollup
 78	   * query (there is no rollup layer at this stage; see file header).
 79	   *
 80	   * @param input.limit - Desired row count; clamped via {@link clampListLimit} to
 81	   *   `[1, MAX_LIST_LIMIT]`, defaulting to {@link DEFAULT_LIST_LIMIT}.
 82	   * @returns A newest-first defensive-copy slice; callers cannot mutate internal state.
 83	   * @complexity O(limit) — a bounded tail slice plus reverse, not a scan of the full buffer.
 84	   * @overallScore 100/100
 85	   */
 86	  list(input: { limit?: number } = {}): NormalizedHit[] {
 87	    const limit = clampListLimit(input.limit);
 88	    return this.hits.slice(-limit).reverse();
 89	  }
 90	}
