138	  const settingsRepo = new SqliteSettingsRepo(db);
139	  // Fire-and-forget, mirroring `identityReady` (see routes/types.ts's `settingsReady` doc) — this
140	  // composition root stays synchronous; consumers await `settingsReady` before relying on the
141	  // migrated value being present.
142	  const settingsReady = seedSettingsFromPresentation({
143	    presentationRepo,
144	    settingsRepo,
145	    clock,
146	    ids: idGen,
