 96	/**
 97	 * One outbound delivery attempt-group: the join of a single delivered domain event to a single
 98	 * matching subscription (core-owned table `webhook_deliveries`). This is an outbox-SHAPED table
 99	 * (mirrors {@link import("../core/ports").OutboxRecord }) but deliberately distinct from the core
100	 * event outbox: one event fans out to N endpoints, each retrying on its own backoff clock, so
225	  /** Failed but still retryable (re-entered "pending" with a future `nextAttemptAt`). */
226	  failed: number;
227	  /** Failed and exhausted `maxAttempts` — transitioned to `dead`. */
228	  dead: number;
229	}
