231	/**
232	 * Stage B: claim due rows, run `webhooks.beforeDispatch`, sign, POST, and record the outcome.
233	 *
234	 * Fail-closed hook semantics (ADR-036 Round-3 audit fold): if any registered `beforeDispatch`
235	 * contributor throws/rejects (or explicitly vetoes via `{ send: false }`), this delivery
236	 * ATTEMPT fails — it is retried on the standard backoff clock (or dead-lettered once attempts
237	 * are exhausted) and the un-filtered/un-redacted envelope is never dispatched. There is no
238	 * fall-through path that reaches `httpClient.send` after a hook failure.
239	 *
240	 * @complexity O(batchSize) delivery attempts, each O(rawBody length) for signing + one HTTP call.
241	 * @overallScore 100
242	 */
243	export async function processDueDeliveries(
244	  required: ProcessDueDeliveriesRequired,
245	  optional: ProcessDueDeliveriesOptional = {}
246	): Promise<ProcessDueDeliveriesResult> {
247	  const { deliveryRepo, subscriptionRepo, envelopeStore, httpClient, signer, clock } = required.deps;
248	  const {
249	    batchSize = 20,
250	    hooks = [],
251	    requestTimeoutMs = 10_000,
252	    maxAttempts = MAX_DELIVERY_ATTEMPTS,
253	    random,
254	  } = optional;
255	
256	  const nowIso = clock.nowIso();
257	  const claimed = await deliveryRepo.claimPending({ batchSize, nowIso });
258	
259	  const result: ProcessDueDeliveriesResult = { processed: claimed.length, delivered: 0, failed: 0, dead: 0 };
260	
261	  for (const row of claimed) {
262	    const outcome = await attemptOneDelivery(row, {
263	      subscriptionRepo,
264	      envelopeStore,
265	      httpClient,
266	      signer,
267	      hooks,
268	      requestTimeoutMs,
269	    });
270	
271	    if (outcome.ok) {
272	      await deliveryRepo.markDelivered({
273	        workspaceId: row.workspaceId,
274	        id: row.id,
275	        responseStatus: outcome.responseStatus,
276	        deliveredAtIso: clock.nowIso(),
277	      });
278	      result.delivered += 1;
279	      continue;
280	    }
281	
282	    const isExhausted = row.attempts >= maxAttempts;
283	    const nextStatus = isExhausted ? "dead" : "failed";
284	    const failedAtIso = clock.nowIso();
285	    const nextAttemptAt = isExhausted
286	      ? failedAtIso
287	      : addMsToIso(failedAtIso, computeBackoffMs(row.attempts, { random }));
288	
289	    await deliveryRepo.markFailed({
290	      workspaceId: row.workspaceId,
291	      id: row.id,
292	      error: outcome.error,
293	      responseStatus: outcome.responseStatus,
294	      nextStatus,
295	      nextAttemptAt,
296	      deadAtIso: isExhausted ? failedAtIso : undefined,
297	    });
298	
299	    if (isExhausted) result.dead += 1;
300	    else result.failed += 1;
301	  }
302	
303	  return result;
304	}
305	
306	type DeliveryAttemptOutcome =
307	  | { ok: true; responseStatus: number }
308	  | { ok: false; error: string; responseStatus: number | null };
309	
310	/**
311	 * One claimed row's full attempt: resolve subscription + envelope, run hooks, sign, POST.
312	 * Every failure mode (missing subscription, paused/disabled subscription, missing envelope, a
313	 * throwing/vetoing hook, a transport error, a non-2xx response) funnels into the same
314	 * `{ ok: false }` shape so the caller's retry/backoff/dead-letter logic is a single code path.
315	 */
316	async function attemptOneDelivery(
317	  row: WebhookDeliveryRecord,
318	  deps: {
319	    subscriptionRepo: WebhookSubscriptionRepoPort;
320	    envelopeStore: DeliveryEnvelopeStore;
321	    httpClient: HttpClientPort;
322	    signer: WebhookSigner;
323	    hooks: readonly WebhookBeforeDispatchHook[];
324	    requestTimeoutMs: number;
325	  }
326	): Promise<DeliveryAttemptOutcome> {
327	  try {
328	    const subscription = await deps.subscriptionRepo.findById({
329	      workspaceId: row.workspaceId,
330	      id: row.subscriptionId,
331	    });
332	    if (!subscription) {
333	      return { ok: false, error: `subscription '${row.subscriptionId}' was not found`, responseStatus: null };
334	    }
335	    if (subscription.status !== "active") {
336	      return {
337	        ok: false,
338	        error: `subscription '${row.subscriptionId}' is '${subscription.status}', not active`,
339	        responseStatus: null,
340	      };
341	    }
342	
343	    const storedEnvelope = await deps.envelopeStore.find({ deliveryId: row.id });
344	    if (!storedEnvelope) {
345	      return { ok: false, error: `no envelope recorded for delivery '${row.id}'`, responseStatus: null };
346	    }
347	
348	    // Fail-closed: any hook throwing/rejecting propagates out of this try block and becomes a
349	    // failed attempt below — it never falls through to httpClient.send with an unfiltered body.
350	    const envelope = await runBeforeDispatchHooks(deps.hooks, { subscription, envelope: storedEnvelope });
351	
352	    const rawBody = JSON.stringify(envelope);
353	    const timestampSeconds = Math.floor(Date.now() / 1000);
354	    const signatureHeader = await deps.signer.signForSubscription({
355	      subscription,
356	      rawBody,
357	      timestampSeconds,
358	    });
359	
360	    const response = await deps.httpClient.send({
361	      method: "POST",
362	      url: subscription.targetUrl,
363	      headers: {
364	        "content-type": "application/json",
365	        "tovu-signature": signatureHeader,
366	        "tovu-delivery-id": row.id,
367	        "tovu-event-id": row.eventId,
368	      },
369	      body: rawBody,
370	      timeoutMs: deps.requestTimeoutMs,
371	    });
372	
373	    if (response.status >= 200 && response.status < 300) {
374	      return { ok: true, responseStatus: response.status };
375	    }
376	    return {
377	      ok: false,
378	      error: `non-2xx response: ${response.status}`,
379	      responseStatus: response.status,
380	    };
381	  } catch (err) {
382	    const message = err instanceof Error ? err.message : "unknown webhook delivery error";
383	    return { ok: false, error: message, responseStatus: null };
384	  }
385	}
